-- SELECT only. Includes PostgreSQL 17 MAINTAIN; verify version in 00 first.
WITH target AS (
 SELECT c.*,n.nspname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relkind IN ('r','p')
), roles AS (SELECT * FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')),
raw_acl AS (
 SELECT 'table' kind,c.nspname schema,c.relname object,'' subobject,a.privilege_type,a.is_grantable FROM target c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))a WHERE a.grantee=0
 UNION ALL SELECT 'column',c.nspname,c.relname,att.attname,a.privilege_type,a.is_grantable FROM target c JOIN pg_attribute att ON att.attrelid=c.oid CROSS JOIN LATERAL aclexplode(att.attacl)a WHERE a.grantee=0 AND att.attnum>0 AND NOT att.attisdropped
 UNION ALL SELECT 'function',n.nspname,p.proname||'('||oidvectortypes(p.proargtypes)||')','',a.privilege_type,a.is_grantable FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a WHERE a.grantee=0 AND p.prokind='f' AND n.nspname IN ('public','chat_private','group_mvp_private')
 UNION ALL SELECT 'schema',n.nspname,n.nspname,'',a.privilege_type,a.is_grantable FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner)))a WHERE a.grantee=0 AND n.nspname IN ('public','auth','extensions','cron','chat_private','group_mvp_private')
)
SELECT jsonb_build_object(
 'roles',(SELECT jsonb_agg(jsonb_build_object('role',rolname,'superuser',rolsuper,'bypass_rls',rolbypassrls,'inherit',rolinherit,'login',rolcanlogin) ORDER BY rolname) FROM roles),
 'memberships',(SELECT coalesce(jsonb_agg(jsonb_build_object('member',r.rolname,'parent',p.rolname,'admin_option',m.admin_option) ORDER BY r.rolname,p.rolname),'[]'::jsonb) FROM roles r JOIN pg_auth_members m ON m.member=r.oid JOIN pg_roles p ON p.oid=m.roleid),
 'tables',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'role',r.rolname,'privilege',v.p,'allowed',has_table_privilege(r.oid,c.oid,v.p),'grant_option',has_table_privilege(r.oid,c.oid,v.p||' WITH GRANT OPTION')) ORDER BY c.relname,r.rolname,v.p) FROM target c CROSS JOIN roles r CROSS JOIN (VALUES('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER'),('MAINTAIN'))v(p)),
 'columns',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'role',r.rolname,'privilege',v.p,'allowed',has_column_privilege(r.oid,c.oid,a.attnum,v.p),'grant_option',has_column_privilege(r.oid,c.oid,a.attnum,v.p||' WITH GRANT OPTION')) ORDER BY c.relname,a.attnum,r.rolname,v.p) FROM target c JOIN pg_attribute a ON a.attrelid=c.oid CROSS JOIN roles r CROSS JOIN (VALUES('SELECT'),('INSERT'),('UPDATE'),('REFERENCES'))v(p) WHERE a.attnum>0 AND NOT a.attisdropped),
 'functions',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',oidvectortypes(p.proargtypes),'role',r.rolname,'execute',has_function_privilege(r.oid,p.oid,'EXECUTE'),'grant_option',has_function_privilege(r.oid,p.oid,'EXECUTE WITH GRANT OPTION')) ORDER BY n.nspname,p.proname,oidvectortypes(p.proargtypes),r.rolname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN roles r WHERE n.nspname IN ('public','chat_private','group_mvp_private') AND p.prokind='f'),
 'schemas',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'role',r.rolname,'usage',has_schema_privilege(r.oid,n.oid,'USAGE'),'create',has_schema_privilege(r.oid,n.oid,'CREATE'),'usage_grant_option',has_schema_privilege(r.oid,n.oid,'USAGE WITH GRANT OPTION'),'create_grant_option',has_schema_privilege(r.oid,n.oid,'CREATE WITH GRANT OPTION')) ORDER BY n.nspname,r.rolname) FROM pg_namespace n CROSS JOIN roles r WHERE n.nspname IN ('public','auth','extensions','cron','chat_private','group_mvp_private')),
 'public_acl',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY kind,schema,object,subobject,privilege_type),'[]'::jsonb) FROM raw_acl a),
 'default_acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('creator',pg_get_userbyid(d.defaclrole),'schema',coalesce(n.nspname,'<global>'),'type',d.defaclobjtype,'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grant_option',a.is_grantable) ORDER BY d.defaclrole,n.nspname,d.defaclobjtype,a.grantee,a.privilege_type),'[]'::jsonb) FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace CROSS JOIN LATERAL aclexplode(d.defaclacl)a WHERE pg_get_userbyid(d.defaclrole) IN ('postgres','supabase_admin'))
) AS effective_privileges;
